SELECT 'SIG' AS kind, s.id, s.generated_at AS t, s.decision AS d, s.original_decision AS od, s.total_score, s.confidence_score, NULL AS reason FROM trade_signal s WHERE s.symbol = 'DOGEUSDT' AND s.interval_code = '1m' AND s.generated_at BETWEEN '2026-10-12 03:32:00' AND '2026-10-12 04:02:03' UNION ALL SELECT 'WT', w.id, w.executed_at, w.side, NULL, NULL, NULL, w.execution_reason FROM wallet_trade w WHERE w.symbol = 'DOGEUSDT' AND w.executed_at BETWEEN '2026-10-12 03:00:00' AND '2026-10-12 04:02:05' ORDER BY t LIMIT 60